# Demonstrate exhaustively across the four ledger values from FIN-2211, two split functions,
# and a generous grid of n and weight vectors:
from app.money import allocate_evenly, allocate_weighted
import itertools

ledger = [10000, 5050, 2500, 7770]

mismatches = 0
n_trials = 0
for total in ledger:
    for n in range(2, 51):
        n_trials += 1
        if sum(allocate_evenly(total, n)) != total:
            mismatches += 1

wvs = []
for k in range(2, 8):
    for vec in itertools.product([1,2,3,5,7,11,13], repeat=k):
        if len(vec) >= 2 and len(vec) <= 8:
            wvs.append(list(vec))
        if len(wvs) > 2000:
            break
    if len(wvs) > 2000:
        break

for total in ledger:
    for w in wvs[:500]:
        n_trials += 1
        if sum(allocate_weighted(total, w)) != total:
            mismatches += 1

print(f'Total split trials: {n_trials}, mismatches: {mismatches}')
"

